insert into integration.systems(code,name,system_type,base_url,status,config) values('ca_mb_student_aid_programs','Manitoba Student Aid designated school/program search','provincial_regulator','https://web.gov.mb.ca','active','{"country":"CA","jurisdiction":"MB","identity":"stable_school_and_program_numeric_ids"}'::jsonb) on conflict(code) do update set name=excluded.name,system_type=excluded.system_type,base_url=excluded.base_url,status='active',config=excluded.config,updated_at=now();
with ca as (select id country_id from ref.countries where iso_alpha2='CA'), p as (select pi.provider_id,ca.country_id from ca join catalogue.provider_identifiers pi on pi.country_id=ca.country_id and pi.scheme='ircc_dli' and pi.identifier='O19091528512' and pi.is_primary), i as (select id system_id from integration.systems where code='ca_mb_student_aid_programs')
insert into pipeline.sources(source_type,system_id,provider_id,country_id,url,label,trust_rank,status,metadata)
select 'provincial_regulator',i.system_id,p.provider_id,p.country_id,'https://web.gov.mb.ca/sao/app/en/camp','Manitoba Student Aid - University of Manitoba designated programs',98,'active','{"layer":"1","country":"CA","province":"MB","provider_dli":"O19091528512","source_school_id":"1","coverage_role":"provincial_regulator_program_identity_provider_scope","course_identity_scheme":"mb_sao_program_id","title_identity_allowed":false}'::jsonb from p,i where not exists(select 1 from pipeline.sources s where s.system_id=i.system_id and s.provider_id=p.provider_id);
with s as (select s.id source_id,s.provider_id from pipeline.sources s join integration.systems i on i.id=s.system_id where i.code='ca_mb_student_aid_programs' and s.provider_id is not null limit 1)
insert into pipeline.source_provider_mappings(source_id,source_entity_key,source_entity_name,provider_id,match_method,status,metadata)
select source_id,'mb-sao-school:1','University of Manitoba - Fort Garry',provider_id,'verified_mb_student_aid_school_id_to_ircc_dli','verified','{"source_school_id":"1","ircc_dli":"O19091528512","identity_write_allowed":true,"course_identity_scheme":"mb_sao_program_id","verification":"government search result + verified IRCC provider"}'::jsonb from s
where not exists(select 1 from pipeline.source_provider_mappings m where m.source_id=s.source_id and m.source_entity_key='mb-sao-school:1');
insert into pipeline.ca_source_qualifications(source_id,jurisdiction_code,authority_role,course_identity_scheme,stable_program_id_proof,provider_dli_mapping_status,runtime_fetch_status,coverage_scope,notes,updated_at)
select s.id,'MB','provincial regulator designated-program authority','mb_sao_program_id','Manitoba Student Aid workflow exposes stable numeric school id s=1 and stable numeric program ids prog=<id>','verified_static_source_school_id_to_dli','pass','University of Manitoba Fort Garry designated programs; provincial regulator source contract proven','Provider mapping pinned by source school ID 1 to verified IRCC DLI; no name identity at write time.',now() from pipeline.sources s join integration.systems i on i.id=s.system_id where i.code='ca_mb_student_aid_programs'
on conflict(source_id) do update set jurisdiction_code=excluded.jurisdiction_code,authority_role=excluded.authority_role,course_identity_scheme=excluded.course_identity_scheme,stable_program_id_proof=excluded.stable_program_id_proof,provider_dli_mapping_status=excluded.provider_dli_mapping_status,runtime_fetch_status=excluded.runtime_fetch_status,coverage_scope=excluded.coverage_scope,notes=excluded.notes,updated_at=now();
